func segmentIsEmpty(segment segmentDiffView) bool {
	return len(segment.AddedChanges) == 0 &&
		len(segment.MissingChanges) == 0 &&
		len(segment.InconsistentChanges) == 0 &&
		!segment.Version.Changed &&
